intro = "MAIR Lab is a research group at Huazhong University of Science and Technology studying multimodal intelligence across perception, generation, reasoning, and action."
paragraphs = [
  "Our research connects multimodal intelligence, physical intelligence, and AI for science. We study not only how models understand and generate information, but also how they acquire actionable representations of environments and support scientific discovery.",
  "Across these directions, we develop datasets, benchmarks, learning and alignment methods, and interactive systems. Our goal is to turn advances in foundation models into reliable intelligence for complex digital, physical, and scientific settings."
]
focus_heading = "Research perspective"
focus_items = [
  "Connect understanding and generation within unified multimodal systems.",
  "Close the loop from perception and reasoning to interaction and action.",
  "Build scientifically grounded AI systems whose outputs remain useful and correct."
]
